package main
import("encoding/json";"net/http";"strings";"github.com/jackc/pgx/v5/pgxpool")
func registerStockApprovals(m *http.ServeMux,db *pgxpool.Pool){m.HandleFunc("GET /inventory/adjustment-requests",jsonAPI(authenticated(db,stockRoles...)(listAdjustmentRequests(db))));m.HandleFunc("POST /inventory/adjustment-requests",jsonAPI(authenticated(db,stockRoles...)(createAdjustmentRequest(db))));m.HandleFunc("POST /inventory/adjustment-requests/{id}/{action}",jsonAPI(authenticated(db,stockRoles...)(adjustmentRequestAction(db))))}
func listAdjustmentRequests(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){rows,e:=db.Query(r.Context(),`SELECT q.id,p.name,p.sku,q.system_quantity,q.physical_quantity,q.difference,q.reason,COALESCE(q.notes,''),q.status,COALESCE(u.name,'System'),q.created_at FROM stock_adjustment_requests q JOIN products p ON p.id=q.product_id LEFT JOIN users u ON u.id=q.requested_by WHERE q.tenant_id=$1 ORDER BY q.created_at DESC`,claimsFrom(r).Tenant);if e!=nil{http.Error(w,e.Error(),500);return};defer rows.Close();out:=[]map[string]any{};for rows.Next(){var id,name,sku,reason,notes,status,user string;var system,physical,diff float64;var at any;rows.Scan(&id,&name,&sku,&system,&physical,&diff,&reason,&notes,&status,&user,&at);out=append(out,map[string]any{"id":id,"product":name,"sku":sku,"systemQuantity":system,"physicalQuantity":physical,"quantity":diff,"reason":reason,"notes":notes,"status":status,"user":user,"createdAt":at})};json.NewEncoder(w).Encode(out)}}
func createAdjustmentRequest(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){var x struct{ProductID,Reason,Notes,RequestID string;PhysicalQuantity float64};if json.NewDecoder(r.Body).Decode(&x)!=nil||x.ProductID==""||x.PhysicalQuantity<0||strings.TrimSpace(x.Reason)==""||x.RequestID==""{http.Error(w,"product, physical quantity, reason and request ID required",400);return};c:=claimsFrom(r);var id string;e:=db.QueryRow(r.Context(),`INSERT INTO stock_adjustment_requests(tenant_id,branch_id,product_id,system_quantity,physical_quantity,difference,reason,notes,requested_by,client_request_id) SELECT $1,$2,p.id,COALESCE(b.quantity,0),$4,$4-COALESCE(b.quantity,0),$5,NULLIF($6,''),NULLIF($7,'')::uuid,$8 FROM products p LEFT JOIN branch_stock b ON b.product_id=p.id AND b.branch_id=$2 WHERE p.id=$3 AND p.tenant_id=$1 AND p.is_active AND $4<>COALESCE(b.quantity,0) RETURNING id`,c.Tenant,c.Branch,x.ProductID,x.PhysicalQuantity,strings.TrimSpace(x.Reason),strings.TrimSpace(x.Notes),c.Sub,x.RequestID).Scan(&id);if e!=nil{http.Error(w,"stock matches, product invalid, or request duplicated",409);return};auditUserAction(r,db,"STOCK_ADJUSTMENT_REQUESTED",id,x);w.WriteHeader(201);json.NewEncoder(w).Encode(map[string]string{"id":id,"status":"draft"})}}
func adjustmentRequestAction(db *pgxpool.Pool)http.HandlerFunc{return func(w http.ResponseWriter,r *http.Request){id,action:=r.PathValue("id"),r.PathValue("action");var x struct{Reason string};json.NewDecoder(r.Body).Decode(&x);if action!="approve"&&action!="reject"&&action!="finalize"&&action!="cancel"{http.Error(w,"invalid action",404);return};if(action=="reject"||action=="cancel")&&strings.TrimSpace(x.Reason)==""{http.Error(w,"reason required",400);return};c:=claimsFrom(r);tx,e:=db.Begin(r.Context());if e!=nil{http.Error(w,e.Error(),500);return};defer tx.Rollback(r.Context());var product,branch,status,reason,notes string;var system,physical,diff float64;e=tx.QueryRow(r.Context(),`SELECT product_id,branch_id,status,system_quantity,physical_quantity,difference,reason,COALESCE(notes,'') FROM stock_adjustment_requests WHERE id=$1 AND tenant_id=$2 FOR UPDATE`,id,c.Tenant).Scan(&product,&branch,&status,&system,&physical,&diff,&reason,&notes);if e!=nil{http.Error(w,"request not found",404);return};next:="";if action=="approve"&&status=="draft"{next="approved";_,e=tx.Exec(r.Context(),`UPDATE stock_adjustment_requests SET status='approved',approved_by=NULLIF($2,'')::uuid,approved_at=now() WHERE id=$1`,id,c.Sub)}else if action=="finalize"&&status=="approved"{next="finalized";var current float64;e=tx.QueryRow(r.Context(),`SELECT quantity FROM branch_stock WHERE product_id=$1 AND branch_id=$2 FOR UPDATE`,product,branch).Scan(&current);if e==nil&&current!=system{http.Error(w,"stock changed after request; create a new count",409);return};if e==nil{_,e=tx.Exec(r.Context(),`UPDATE branch_stock SET quantity=$3 WHERE product_id=$1 AND branch_id=$2`,product,branch,physical)};var balance float64;if e==nil{e=tx.QueryRow(r.Context(),`UPDATE products SET stock_quantity=stock_quantity+$1 WHERE id=$2 RETURNING stock_quantity`,diff,product).Scan(&balance)};var adjustment string;if e==nil{e=tx.QueryRow(r.Context(),`INSERT INTO stock_adjustments(tenant_id,branch_id,product_id,system_quantity,physical_quantity,quantity,reason,notes,adjusted_by,status)VALUES($1,$2,$3,$4,$5,$6,$7,$8,$9,'finalized')RETURNING id`,c.Tenant,branch,product,system,physical,diff,reason,notes,c.Sub).Scan(&adjustment)};if e==nil{_,e=tx.Exec(r.Context(),`INSERT INTO stock_movements(product_id,kind,quantity,tenant_id,branch_id,reference_type,reference_id,balance_after,notes,created_by)VALUES($1,'adjustment',$2,$3,$4,'stock_adjustment',$5,$6,$7,$8)`,product,diff,c.Tenant,branch,adjustment,balance,reason,c.Sub)};if e==nil{_,e=tx.Exec(r.Context(),`UPDATE stock_adjustment_requests SET status='finalized',finalized_by=NULLIF($2,'')::uuid,finalized_at=now() WHERE id=$1`,id,c.Sub)}}else if action=="reject"&&status=="draft"{next="rejected";_,e=tx.Exec(r.Context(),`UPDATE stock_adjustment_requests SET status='rejected',decision_reason=$2 WHERE id=$1`,id,strings.TrimSpace(x.Reason))}else if action=="cancel"&&status=="draft"{next="cancelled";_,e=tx.Exec(r.Context(),`UPDATE stock_adjustment_requests SET status='cancelled',decision_reason=$2 WHERE id=$1`,id,strings.TrimSpace(x.Reason))}else{http.Error(w,"action is not allowed in current status",409);return};if e!=nil||tx.Commit(r.Context())!=nil{http.Error(w,"adjustment workflow failed",409);return};auditUserAction(r,db,"STOCK_ADJUSTMENT_"+strings.ToUpper(next),id,x);w.WriteHeader(204)}}
